async ({ http: { request }, workspace: { glob } }) => {
  const H = { "User-Agent": "Mozilla/5.0" };
  const y = (s: string) => `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s)}?period1=473385600&period2=1794787200&interval=1mo`;
  const urls = {
    spx: y("^GSPC"), ndx: y("^IXIC"),
    shiller: "https://raw.githubusercontent.com/datasets/s-and-p-500/main/data/data.csv",
    ff: "https://fred.stlouisfed.org/graph/fredgraph.csv?id=FEDFUNDS",
    t10: "https://fred.stlouisfed.org/graph/fredgraph.csv?id=GS10",
    multpl: "https://www.multpl.com/shiller-pe/table/by-month",
  };
  const ents = Object.entries(urls);
  const r = await Promise.allSettled(ents.map(([, u]) => request(u, { maxBytes: 1_000_000, headers: H })));
  const out: Record<string, PitJsonValue> = {};
  const parseY = (b: string) => { const j = JSON.parse(b).chart.result[0]; return j.timestamp.map((t: number, i: number) => [new Date(t * 1000).toISOString().slice(0, 7), j.indicators.quote[0].close[i]]); };
  for (let i = 0; i < ents.length; i++) {
    const [k] = ents[i]; const x = r[i];
    if (x.status !== "fulfilled") { out[k] = String(x.reason).slice(0, 200); continue; }
    const b = x.value.body;
    if (k === "spx" || k === "ndx") { const d = parseY(b); out[k] = { n: d.length, first: d[0], last: d.slice(-3), sample: d.filter((_: any, j: number) => j % 24 === 0) }; }
    else if (k === "shiller") { const rows = b.trim().split("\n"); const nz = rows.filter((l) => +l.split(",")[9] > 0); out[k] = { lastPE10: nz.slice(-3), y2000: rows.filter((l) => l.startsWith("1999-12") || l.startsWith("2000-03") || l.startsWith("2000-01")) }; }
    else if (k === "multpl") { out[k] = { status: x.value.status, snippet: b.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").slice(b.indexOf("<table") > 0 ? 0 : 0, 0) + (b.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").match(/Date Value.{0,400}/)?.[0] ?? "nomatch") }; }
    else { const rows = b.trim().split("\n"); out[k] = rows.slice(-3).concat(rows.filter((l) => /^(1999|2000)-(01|06|12)/.test(l))); }
  }
  out.docs = (await glob(["docs/**"], { limit: 50 })).entries as PitJsonValue;
  return out as PitJsonValue;
}
